function solve(a,b){if(!b.length||!b[0].length){return[];}const c=b[0].length;const m=new Map();for(const x of b){m.set(x,(m.get(x)||0)+1);}const r=[];for(let i=0;i<c;i++){let d=i;let n=0;const e=new Map();for(let j=i;j+c<=a.length;j+=c){const f=a.slice(j,j+c);if(!m.has(f)){e.clear();n=0;d=j+c;continue;}e.set(f,(e.get(f)||0)+1);n++;while(e.get(f)>m.get(f)){const b=a.slice(d,d+c);e.set(b,e.get(b)-1);d+=c;n--;}if(n===b.length){r.push(d);const b=a.slice(d,d+c);e.set(b,e.get(b)-1);d+=c;n--;}}}return r.sort((a,b)=>a-b);}
